theorem matching_support_card {H M : Finset (Finset V)} {r : ℕ}
    (hr : IsUniform H r) (hM : IsMatching H M) :
    (support M).card = r * M.card

theorem conflicts_card_le_of_uniform {H : Finset (Finset V)} {r Δ : ℕ}
    (hr : IsUniform H r) (hΔ : ∀ x, degree H x ≤ Δ) {e : Finset V} (he : e ∈ H) :
    (conflicts H e).card ≤ r * Δ

theorem prob_edge_hit {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (e : Finset V) :
    (ℙ : Measure Ω) {ω | ∃ x ∈ e, x ∈ support (roundMatching (retainedSet H ρ ω))}
      ≤ ∑ x ∈ e, (degree H x : ENNReal) * ENNReal.ofReal p

theorem prob_edge_hit_le {H : Finset (Finset V)} {p : ℝ} {r Δ : ℕ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hr : IsUniform H r) (hΔ : ∀ x, degree H x ≤ Δ)
    {e : Finset V} (he : e ∈ H) :
    (ℙ : Measure Ω) {ω | ∃ x ∈ e, x ∈ support (roundMatching (retainedSet H ρ ω))}
      ≤ (r : ENNReal) * (Δ : ENNReal) * ENNReal.ofReal p

theorem prob_vertex_covered {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (x : V) :
    (ℙ : Measure Ω) {ω | x ∈ support (roundMatching (retainedSet H ρ ω))}
      ≤ (degree H x : ENNReal) * ENNReal.ofReal p

theorem measurableSet_vertex_covered {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (x : V) :
    MeasurableSet {ω | x ∈ support (roundMatching (retainedSet H ρ ω))}

theorem integrable_matchingSize {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) :
    Integrable (fun ω => ((roundMatching (retainedSet H ρ ω)).card : ℝ)) (ℙ : Measure Ω)

theorem matchingEvent_eq {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) {e : Finset V} (he : e ∈ H) :
    {ω | e ∈ roundMatching (retainedSet H ρ ω)}
      = ρ.A e ∩ ⋂ g ∈ conflicts H e, (ρ.A g)ᶜ

theorem matchingIndicator_integrable {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) {e : Finset V} (he : e ∈ H) :
    Integrable (matchingIndicator ρ e) (ℙ : Measure Ω)

theorem measurableSet_matchingEvent {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) {e : Finset V} (he : e ∈ H) :
    MeasurableSet {ω | e ∈ roundMatching (retainedSet H ρ ω)}

theorem prob_vertex_covered_eq {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hp0 : 0 ≤ p) (hp1 : p ≤ 1) (x : V) :
    (ℙ : Measure Ω).real {ω | x ∈ covered (retainedSet H ρ ω)} = coverRate H p x

theorem vertexCovered_eq_biUnion {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (x : V) :
    {ω | x ∈ covered (retainedSet H ρ ω)}
      = ⋃ f ∈ H.filter (fun f => x ∈ f), {ω | f ∈ roundMatching (retainedSet H ρ ω)}

theorem integrable_safeDegree {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) :
    Integrable (fun ω => (safeDegree H (covered (retainedSet H ρ ω)) v : ℝ)) (ℙ : Measure Ω)

theorem integrable_safeIndicator {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) (e : Finset V) :
    Integrable (safeIndicator ρ v e) (ℙ : Measure Ω)

theorem measurableSet_safeEvent {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) (e : Finset V) :
    MeasurableSet {ω | Disjoint (e.erase v) (covered (retainedSet H ρ ω))}

theorem safeEvent_eq_compl {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) (e : Finset V) :
    {ω | Disjoint (e.erase v) (covered (retainedSet H ρ ω))}
      = (⋃ u ∈ e.erase v, {ω | u ∈ covered (retainedSet H ρ ω)})ᶜ

theorem coverInd_mul {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (u u' : V) :
    (fun ω => coverInd ρ u ω * coverInd ρ u' ω)
      = Set.indicator ({ω | u ∈ covered (retainedSet H ρ ω)}
          ∩ {ω | u' ∈ covered (retainedSet H ρ ω)}) 1

theorem integrable_coverInd {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (u : V) :
    Integrable (coverInd ρ u) (ℙ : Measure Ω)

theorem integrable_coverIndC_mul {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (u u' : V) :
    Integrable (fun ω => coverIndC ρ u ω * coverIndC ρ u' ω) (ℙ : Measure Ω)

theorem integrable_coverInd_mul {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (u u' : V) :
    Integrable (fun ω => coverInd ρ u ω * coverInd ρ u' ω) (ℙ : Measure Ω)

theorem integral_coverInd {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hp0 : 0 ≤ p) (hp1 : p ≤ 1) (u : V) :
    ∫ ω, coverInd ρ u ω ∂(ℙ : Measure Ω) = coverRate H p u

theorem integral_coverIndC_mul {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hp0 : 0 ≤ p) (hp1 : p ≤ 1) (u u' : V) :
    ∫ ω, coverIndC ρ u ω * coverIndC ρ u' ω ∂(ℙ : Measure Ω)
      = (ℙ : Measure Ω).real ({ω | u ∈ covered (retainedSet H ρ ω)}
          ∩ {ω | u' ∈ covered (retainedSet H ρ ω)})
        - coverRate H p u * coverRate H p u'

theorem integral_coverInd_mul {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (u u' : V) :
    ∫ ω, coverInd ρ u ω * coverInd ρ u' ω ∂(ℙ : Measure Ω)
      = (ℙ : Measure Ω).real ({ω | u ∈ covered (retainedSet H ρ ω)}
          ∩ {ω | u' ∈ covered (retainedSet H ρ ω)})

theorem integral_lossWeight {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hp0 : 0 ≤ p) (hp1 : p ≤ 1) (v : V) :
    ∫ ω, lossWeight ρ v ω ∂(ℙ : Measure Ω) = lossWeightMean H p v

theorem lossWeight_eq' {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) (ω : Ω) :
    (coverWeight H v (covered (retainedSet H ρ ω)) : ℝ) = lossWeight ρ v ω

theorem exists_notMem_of_measureReal_add_lt_one {A B : Set Ω}
    (h : (ℙ : Measure Ω).real A + (ℙ : Measure Ω).real B < 1) :
    ∃ ω : Ω, ω ∉ A ∧ ω ∉ B

theorem coveredCount_eq_sum {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (ω : Ω) :
    ((covered (retainedSet H ρ ω)).card : ℝ) = ∑ v : V, coverInd ρ v ω

theorem integrable_coveredCount [Finite V] {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) :
    Integrable (fun ω => ((covered (retainedSet H ρ ω)).card : ℝ)) (ℙ : Measure Ω)

theorem integrable_pairCount {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) :
    Integrable (pairCount ρ v) (ℙ : Measure Ω)

theorem integrable_sq_centered_lossWeight {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) :
    Integrable (fun ω => (lossWeight ρ v ω - lossWeightMean H p v) ^ 2) (ℙ : Measure Ω)

theorem integrable_tightBad {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (t s : ℝ) :
    Integrable (tightBad ρ t s) (ℙ : Measure Ω)

theorem integral_pairCount_le {H : Finset (Finset V)} {p : ℝ} {r : ℕ} {εpair : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hr : IsUniform H r) (hr1 : 1 ≤ r)
    (hpair : ∀ u u' : V, u ≠ u' →
      (ℙ : Measure Ω).real ({ω | u ∈ covered (retainedSet H ρ ω)}
        ∩ {ω | u' ∈ covered (retainedSet H ρ ω)}) ≤ εpair) (hε0 : 0 ≤ εpair) (v : V) :
    ∫ ω, pairCount ρ v ω ∂(ℙ : Measure Ω) ≤ (degree H v : ℝ) * ((r : ℝ) - 1) ^ 2 * εpair

theorem pairWeight_le_pairCount {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) (ω : Ω) :
    (pairWeight H v (covered (retainedSet H ρ ω)) : ℝ) ≤ pairCount ρ v ω

theorem tightBad_nonneg {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) {t s : ℝ} (ht : 0 < t) (hs : 0 < s) (ω : Ω) :
    0 ≤ tightBad ρ t s ω

theorem prob_matchingEvent {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hp0 : 0 ≤ p) (hp1 : p ≤ 1)
    {e : Finset V} (he : e ∈ H) :
    (ℙ : Measure Ω).real {ω | e ∈ roundMatching (retainedSet H ρ ω)}
      = p * (1 - p) ^ (conflicts H e).card

theorem prob_two_matched_disjoint {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (hp0 : 0 ≤ p) (hp1 : p ≤ 1)
    {f g : Finset V} (hf : f ∈ H) (hg : g ∈ H) (hne : f ≠ g) (hdisj : Disjoint f g) :
    (ℙ : Measure Ω) ({ω | f ∈ roundMatching (retainedSet H ρ ω)}
        ∩ {ω | g ∈ roundMatching (retainedSet H ρ ω)})
      = ENNReal.ofReal (p ^ 2 * (1 - p) ^ (conflicts H f ∪ conflicts H g).card)

theorem prob_two_matched_of_not_disjoint {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) {f g : Finset V} (hne : f ≠ g)
    (hmeet : ¬ Disjoint f g) :
    ({ω | f ∈ roundMatching (retainedSet H ρ ω)}
        ∩ {ω | g ∈ roundMatching (retainedSet H ρ ω)}) = (∅ : Set Ω)

theorem twoCovered_eq_biUnion {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (u u' : V) :
    ({ω | u ∈ covered (retainedSet H ρ ω)} ∩ {ω | u' ∈ covered (retainedSet H ρ ω)})
      = ⋃ f ∈ H.filter (fun f => u ∈ f), ⋃ g ∈ H.filter (fun g => u' ∈ g),
          ({ω | f ∈ roundMatching (retainedSet H ρ ω)}
            ∩ {ω | g ∈ roundMatching (retainedSet H ρ ω)})

theorem twoMatchedEvent_eq {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) {f g : Finset V} (hf : f ∈ H) (hg : g ∈ H) :
    ({ω | f ∈ roundMatching (retainedSet H ρ ω)}
        ∩ {ω | g ∈ roundMatching (retainedSet H ρ ω)})
      = (ρ.A f ∩ ρ.A g) ∩ ⋂ h ∈ (conflicts H f ∪ conflicts H g), (ρ.A h)ᶜ

theorem lossWeightMean_ge {H : Finset (Finset V)} {p : ℝ} {r : ℕ} {qlo : ℝ}
    (hr : IsUniform H r) (hr1 : 1 ≤ r) (hqlo : ∀ u : V, qlo ≤ coverRate H p u) (v : V) :
    ((r : ℝ) - 1) * (degree H v : ℝ) * qlo ≤ lossWeightMean H p v

theorem lossWeightMean_le {H : Finset (Finset V)} {p : ℝ} {r : ℕ} {qhi : ℝ}
    (hr : IsUniform H r) (hr1 : 1 ≤ r) (hqhi : ∀ u : V, coverRate H p u ≤ qhi) (v : V) :
    lossWeightMean H p v ≤ ((r : ℝ) - 1) * (degree H v : ℝ) * qhi

theorem integrable_safeBad {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (t : ℝ) :
    Integrable (safeBad ρ t) (ℙ : Measure Ω)

theorem integrable_safeIndicator_mul {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) (e e' : Finset V) :
    Integrable (fun ω => safeIndicator ρ v e ω * safeIndicator ρ v e' ω) (ℙ : Measure Ω)

theorem mem_roundMatching_insert_iff_erase {R : Finset (Finset V)} {e f : Finset V}
    (hf : f ∉ flipInfluence R e) :
    f ∈ roundMatching (insert e R) ↔ f ∈ roundMatching (R.erase e)

theorem safeIndicator_mul_eq {H : Finset (Finset V)} {p : ℝ}
    (ρ : BernoulliRetention (Ω := Ω) H p) (v : V) (e e' : Finset V) (ω : Ω) :
    safeIndicator ρ v e ω * safeIndicator ρ v e' ω
      = if ω ∈ {ω | Disjoint (e.erase v) (covered (retainedSet H ρ ω))}
            ∩ {ω | Disjoint (e'.erase v) (covered (retainedSet H ρ ω))} then 1 else 0

theorem nibbleMatchingSeq_isMatching {R : ℕ → Finset (Finset V) → Finset (Finset V)}
    (hR : ∀ k H', R k H' ⊆ H') (H : Finset (Finset V)) (k : ℕ) :
    IsMatching H (nibbleMatchingSeq R H k)

theorem nibbleMatchingSeq_subset {R : ℕ → Finset (Finset V) → Finset (Finset V)}
    (hR : ∀ k H', R k H' ⊆ H') (H : Finset (Finset V)) (k : ℕ) :
    nibbleMatchingSeq R H k ⊆ H

theorem nibbleResidualSeq_disjoint_support {R : ℕ → Finset (Finset V) → Finset (Finset V)}
    (H : Finset (Finset V)) (k : ℕ) :
    ∀ e ∈ nibbleResidualSeq R H k, Disjoint e (support (nibbleMatchingSeq R H k))

theorem lostDegree_union_of_disjoint {K : Finset (Finset V)} {S E : Finset V}
    (hS : ∀ e ∈ K, Disjoint e S) (v : V) :
    lostDegree K (S ∪ E) v = lostDegree K E v

theorem oracleStrategy_subset {G : Finset (Finset V) → Finset V → Finset (Finset V)}
    (hG : ∀ H' S, G H' S ⊆ H') (H : Finset (Finset V)) (k : ℕ) (H' : Finset (Finset V)) :
    oracleStrategy G H k H' ⊆ H'

theorem uncoveredCount_antitone {R : ℕ → Finset (Finset V) → Finset (Finset V)}
    (hR : ∀ k H', R k H' ⊆ H') (H : Finset (Finset V)) (k : ℕ) :
    uncoveredCount R H (k + 1) ≤ uncoveredCount R H k

theorem uncovered_step {a b : ℕ → ℝ} {lam : ℝ}
    (hstep : ∀ k, a (k + 1) ≤ a k - b k) (hcov : ∀ k, (1 - lam) * a k ≤ b k) :
    ∀ k, a (k + 1) ≤ lam * a k

theorem weak_duality (inc : O → Finset C) {w : O → ℝ} {y : C → ℝ}
    (hw : IsPacking inc w) (hy : IsCover inc y) :
    ∑ o, w o ≤ ∑ c, y c

theorem HasNearRegularFamily.mono_eps {G : SimpleGraph V} [DecidableRel G.Adj] {ε ε' μ η d₀ : ℝ}
    (h : HasNearRegularFamily G ε μ η d₀) (hεε' : ε ≤ ε') :
    HasNearRegularFamily G ε' μ η d₀

theorem fracMatching_sum_le {W : Type} [Fintype W] [DecidableEq W] {H : Finset (Finset W)}
    {r : ℕ} (hr : IsUniform H r) {w : Finset W → ℝ}
    (hcon : ∀ v : W, ∑ T ∈ H.filter (fun T => v ∈ T), w T ≤ 1) :
    (r : ℝ) * (∑ T ∈ H, w T) ≤ (Fintype.card W : ℝ)

theorem card_filter_product {α β : Type*} (s : Finset α) (t : Finset β)
    (P : α × β → Prop) [DecidablePred P] :
    #{e ∈ s ×ˢ t | P e} = ∑ x ∈ s, #{y ∈ t | P (x, y)}

theorem edgeTriangleDegree_pair (G : SimpleGraph V) [DecidableRel G.Adj] {x y : V}
    (hxy : G.Adj x y) :
    edgeTriangleDegree G {x, y} = #{z ∈ (univ : Finset V) | G.Adj x z ∧ G.Adj y z}

theorem tripleGraph_edgeDisjoint_of_rect_disjoint (G : SimpleGraph V) {A B C A' B' C' : Finset V}
    (h : Disjoint (tripleRect A B C) (tripleRect A' B' C')) (x y : V)
    (hxy : (tripleGraph G A B C).Adj x y) : ¬ (tripleGraph G A' B' C').Adj x y

theorem rect_le_pairArea (G : SimpleGraph V) [DecidableRel G.Adj] {R : Finset (V × V)}
    {S T D E : Finset V} (hDS : D ⊆ S) (hET : E ⊆ T) (hDE : (D ×ˢ E) ⊆ R) :
    (G.edgeDensity S T : ℝ) * (#D : ℝ) * (#E : ℝ) ≤ pairArea G R (S, T)

theorem regularityReduced_parts_ne (G : SimpleGraph V) [DecidableRel G.Adj]
    (P : Finpartition (univ : Finset V)) {ep de : ℝ} {a b : V}
    (hab : (G.regularityReduced P ep de).Adj a b) {A B : Finset V}
    (hA : A ∈ P.parts) (hB : B ∈ P.parts) (ha : a ∈ A) (hb : b ∈ B) : A ≠ B

theorem card_blowUp_fiber (H : SimpleGraph W) [DecidableRel H.Adj] (q : ℕ) {t : Finset W}
    (ht : H.IsNClique 3 t) :
    #(((blowUp H q).cliqueFinset 3).filter (fun t' => t'.image Prod.fst = t)) = q ^ 3

theorem partClass_card_three_of_isNClique (G : SimpleGraph V) [DecidableRel G.Adj]
    (P : Finpartition (univ : Finset V)) (ep de : ℝ) {t : Finset V}
    (ht : (G.regularityReduced P ep de).IsNClique 3 t) : #(partClass P t) = 3

theorem exists_positions_of_mem_tripleRect {f : ZMod 3 → Finset V} {x y : V}
    (h : (x, y) ∈ tripleRect (f 0) (f 1) (f 2)) :
    ∃ a b : ZMod 3, a ≠ b ∧ x ∈ f a ∧ y ∈ f b

theorem pick3_spec {ι : Type} [Nonempty ι] [DecidableEq ι] {t : Finset ι} (h3 : #t = 3) :
    (pick3 t).1 ≠ (pick3 t).2.1 ∧ (pick3 t).1 ≠ (pick3 t).2.2 ∧
      (pick3 t).2.1 ≠ (pick3 t).2.2 ∧ t = {(pick3 t).1, (pick3 t).2.1, (pick3 t).2.2}

theorem nibbleMatching_isMatching {R : Finset (Finset V) → Finset (Finset V)}
    (hR : ∀ H', R H' ⊆ H') (H : Finset (Finset V)) (k : ℕ) :
    IsMatching H (nibbleMatching R H k)

theorem nibbleMatching_subset {R : Finset (Finset V) → Finset (Finset V)}
    (hR : ∀ H', R H' ⊆ H') (H : Finset (Finset V)) (k : ℕ) :
    nibbleMatching R H k ⊆ H

theorem nibbleResidual_disjoint_support {R : Finset (Finset V) → Finset (Finset V)}
    (H : Finset (Finset V)) (k : ℕ) :
    ∀ e ∈ nibbleResidual R H k, Disjoint e (support (nibbleMatching R H k))

theorem sum_weightedLoad (H : Finset (Finset V)) (w : Finset V → ℝ) {r : ℕ}
    (hr : IsUniform H r) :
    ∑ v : V, weightedLoad H w v = (r : ℝ) * ∑ e ∈ H, w e

theorem weightedSum_le_card (H : Finset (Finset V)) (w : Finset V → ℝ) {r : ℕ}
    (hr : IsUniform H r) (hload : ∀ v : V, weightedLoad H w v ≤ 1) :
    (r : ℝ) * (∑ e ∈ H, w e) ≤ (Fintype.card V : ℝ)

lemma card_mixedPart_le (hm : 0 < m) {M : Finset (Finset (Pad X m))}
    (hM : IsMatching (padFam K m) M) :
    ((M.filter (fun U => U.toRight ≠ ∅)).card : ℝ) ≤ (m : ℝ)
